import { AxisBaseOption } from '../src/coord/axisCommonTypes';

function makeValueAxis(axisOption: AxisBaseOption, extent: [number, number]): Axis {
    const scale = new IntervalScale();
    scale.setExtent(extent[0], extent[1]);
    scale.calcNiceTicks();
    const axis = new Axis('x', scale, [0, 500]);
    axis.type = 'value';
    axis.model = new Model(axisOption) as unknown as AxisBaseModel;
    return axis;
}

function makeTimeAxis(axisOption: AxisBaseOption, extent: [number, number]): Axis {
    const scale = new TimeScale();
    scale.setExtent(extent[0], extent[1]);
    const axis = new Axis('x', scale, [0, 500]);
    axis.type = 'time';
    axis.model = new Model(axisOption) as unknown as AxisBaseModel;
    return axis;
}

